// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartContext } from './CartContext';
import { PaymentContext } from './PaymentContext';

const mockItems = [
  { id: '1', name: 'Guzzoline', price: 29.99 },
  { id: '2', name: 'Chrome Paint', price: 15.00 }
];

const renderCheckout = (cartItems = mockItems, paymentMock = vi.fn()) => {
  const cartValue = {
    items: cartItems,
    total: cartItems.reduce((sum, i) => sum + i.price, 0),
    clearCart: vi.fn()
  };

  return render(
    <CartContext.Provider value={cartValue}>
      <PaymentContext.Provider value={{ processPayment: paymentMock }}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentContext.Provider>
    </CartContext.Provider>
  );
};

describe('Checkout - The Path Through Chaos', () => {
  describe('Happy Path - Seeds We Keep', () => {
    it('completes full checkout flow from shipping to confirmation', async () => {
      const user = userEvent.setup();
      const processPayment = vi.fn().mockResolvedValue({ orderId: 'ORD-V8' });
      renderCheckout(mockItems, processPayment);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Fury Road');
      await user.type(screen.getByLabelText(/city/i), 'Citadel');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Imperator Furiosa');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByRole('region', { name: /order review/i })).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText('ORD-V8')).toBeInTheDocument();
      });
    });
  });

  describe('Validation - Everyone Is Crazy Here', () => {
    it('shows error for invalid ZIP code', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip code/i), 'NOPE');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code/i);
    });
  });

  describe('Edge Cases - Who Orchestrates the Orchestrators?', () => {
    it('shows empty cart message when no items', () => {
      renderCheckout([]);
      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });

    it('handles payment failure gracefully', async () => {
      const user = userEvent.setup();
      const failingPayment = vi.fn().mockRejectedValue(new Error('Insufficient guzzoline'));
      renderCheckout(mockItems, failingPayment);

      // Navigate to review step... then place order
      // Assert error appears with role="alert"
    });
  });
});
